for k,v in old.items():assert new[k]==v,k
for i in [459,458,450,448,445]:
 d=json.loads((root/f'kb/research/writers/enrichment/{i}.json').read_text());assert d['reader_draft']==new[str(i)]
 page=(site/f'poet-{i}.html').read_text()
 for s in new[str(i)]['sections']:
  for p in s['paragraphs']:assert html.escape(p) in page,(i,p)
r=dict(batch='research-062',status='verified',independent=False,writer_ids=[459,458,450,448,445],reader_drafts=5,externally_corroborated=3,source_limited=[459,445],checks=dict(public_build='passed',author_pages='PASS',editions='PASS',preserved_source_files=len(hashes),existing_narratives_preserved=len(old),rendered_narratives=5,browser_visual='Not repeated; prose/data only, approved renderer unchanged.'),limitations=['Independent author/editor review pending.','459 and 445 remain source-limited; no outside identity bridge or books established.','458 teaching duration differs between contributor notes; exact total omitted and search-index access limitations recorded.','450 bibliographic totals vary across source dates; no current count asserted.','448 planting/award/research totals not independently established and omitted.'],resume='research-063',publication='No deployment or push.')
(b/'review.json').write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n')
p=root/'kb/research/writers/enrichment-batches.json';d=json.loads(p.read_text())
